// Array-of-temporal (LIST(blob)) INPUT marshalling for the NxN set-set functions
// (minDistance(tgeo[],tgeo[]) etc.). Reads a DuckDB LIST row's child BLOBs into a fresh
// Temporal** (each element malloc'd by BlobToTemporal); the caller frees via FreeTemporalArr.
inline const Temporal **ListToTemporalArr(Vector &child, list_entry_t le, int *count) {
    auto data = FlatVector::GetData<string_t>(child);
    int n = (int) le.length;
    const Temporal **arr = (const Temporal **) malloc(sizeof(Temporal *) * (n > 0 ? n : 1));
    for (idx_t i = 0; i < le.length; i++) arr[i] = BlobToTemporal(data[le.offset + i]);
    *count = n;
    return arr;
}
inline void FreeTemporalArr(const Temporal **arr, int n) {
    for (int i = 0; i < n; i++) free((void *) arr[i]);
    free((void *) arr);
}
// Build a MEOS text* varlena from a DuckDB VARCHAR (hand binding's exact method); caller frees.
inline text *MakeText(string_t s) {
    size_t len = s.GetSize();
    text *t = (text *)malloc(VARHDRSZ + len);
    SET_VARSIZE(t, VARHDRSZ + len);
    memcpy(VARDATA(t), s.GetData(), len);
    return t;
}
// A geography from a DuckDB GEOMETRY, read as geodetic in the default SRID as MobilityDB
// reads a geography literal; caller frees.
inline GSERIALIZED *GeogFromGeometry(string_t blob) {
    GSERIALIZED *gs = GeometryToGSerialized(blob, 0);
    GSERIALIZED *geog = geom_to_geog(gs);
    free(gs);
    return geog;
}
// text** from a DuckDB LIST(VARCHAR); the caller frees via FreeTextArr. A NULL
// element is a NULL text*, the NULL of the SQL array MEOS reads as PostgreSQL does.
inline text **ListToTextArr(Vector &child, list_entry_t le, int *count) {
    auto data = FlatVector::GetData<string_t>(child);
    auto &valid = FlatVector::Validity(child);
    int n = (int) le.length;
    text **arr = (text **) malloc(sizeof(text *) * (n > 0 ? n : 1));
    for (idx_t i = 0; i < le.length; i++)
        arr[i] = valid.RowIsValid(le.offset + i) ? MakeText(data[le.offset + i]) : nullptr;
    *count = n;
    return arr;
}
inline void FreeTextArr(text **arr, int n) {
    for (int i = 0; i < n; i++) free(arr[i]);
    free(arr);
}
// A text SQL literal (a parameter's DEFAULT 'use_json_null') passed as the `const text *`
// a MEOS function reads, released at the end of the call's full expression, as
// MeosIntervalLiteral passes an interval one.
struct MeosTextLiteral {
    text *p;
    explicit MeosTextLiteral(const char *s) : p(MakeText(string_t(s))) {}
    ~MeosTextLiteral() { free(p); }
    MeosTextLiteral(const MeosTextLiteral &) = delete;
    MeosTextLiteral &operator=(const MeosTextLiteral &) = delete;
    operator const text *() const { return p; }
};
// Convert an owned MEOS Interval* to a DuckDB interval_t and free it.
inline interval_t TakeInterval(MeosInterval *iv) {
    interval_t out = IntervalToIntervalt(iv);
    free(iv);
    return out;
}
// MEOS TimestampTz (PG epoch micros) -> DuckDB timestamp_tz_t.
inline timestamp_tz_t TakeTimestamp(TimestampTz r) {
    timestamp_tz_t ts; ts.value = (int64_t) r; return MeosToDuckDBTimestamp(ts);
}
// Owned MEOS text* varlena -> DuckDB VARCHAR string_t; frees the text*.
inline string_t TakeText(Vector &result, text *t) {
    string_t out = StringVector::AddString(result, (const char *) VARDATA(t), VARSIZE(t) - VARHDRSZ);
    free(t);
    return out;
}
// Owned MEOS C-string (NUL-terminated, malloc'd) -> DuckDB VARCHAR; frees it. A size counts
// the terminator; a writer stating none is read by its terminator.
inline string_t TakeCString(Vector &result, SizedString s) {
    string_t out = s.size ? StringVector::AddString(result, s.s, s.size - 1)
                          : StringVector::AddString(result, s.s);
    free(s.s);
    return out;
}
// A type support writer of MEOS called at the arity the shapes call it, the size it
// states read into the SizedString (#SIZED_CALL of the generator).
template <typename... P, typename... A>
inline SizedString SizedCall(char *(*f)(P...), A... a) {
    size_t size = 0;
    char *s = f(a..., &size);
    return SizedString(s, size);
}

