// ===== @ingroup meos_cbuffer_restrict =====
static void Gen_tcbuffer_at_cbuffer(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    BinaryExecutor::ExecuteWithNulls<string_t, string_t, string_t>(args.data[0], args.data[1], result, args.size(),
        [&](string_t in, string_t a2, ValidityMask &mask, idx_t idx) -> string_t {
            Temporal *t = BlobToTemporal(in);
            Cbuffer *a2p = BlobToCbuffer(a2);
            Temporal *r = tcbuffer_at_cbuffer(t, a2p);
            free(a2p); free(t);
            return TemporalToBlobN(result, r, mask, idx);
        });
}

static void Gen_tcbuffer_at_geom(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const int32_t crs_g = GeometryCrsSrid(args.data[1].GetType());
    BinaryExecutor::ExecuteWithNulls<string_t, string_t, string_t>(args.data[0], args.data[1], result, args.size(),
        [&](string_t in_t, string_t in_g, ValidityMask &mask, idx_t idx) -> string_t {
            Temporal *t = BlobToTemporal(in_t);
            GSERIALIZED *gs = GeometryToGSerialized(in_g, crs_g ? crs_g : tspatial_srid(t));
            if (MEOS_FLAGS_GET_GEODETIC(t->flags)) {
                GSERIALIZED *gs_geog = geom_to_geog(gs);
                free(gs); gs = gs_geog;
            }
            Temporal *r = (Temporal *) tcbuffer_at_geom(t, gs);
            free(t); free(gs);
            return TemporalToBlobN(result, r, mask, idx);
        });
}

static void Gen_tcbuffer_at_stbox(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    TernaryExecutor::ExecuteWithNulls<string_t, string_t, bool, string_t>(args.data[0], args.data[1], args.data[2], result, args.size(),
        [&](string_t in, string_t a2, bool a3, ValidityMask &mask, idx_t idx) -> string_t {
            Temporal *t = BlobToTemporal(in);
            STBox *a2p = BlobToStbox(a2);
            Temporal *r = tcbuffer_at_stbox(t, a2p, a3);
            free(a2p); free(t);
            return TemporalToBlobN(result, r, mask, idx);
        });
}

